#!/usr/bin/env python3
"""Fetch every order page (following "next") and every referenced customer.

Usage: fetch.py <out_dir> [--customers]

Raw responses are saved as JSON under <out_dir>; every non-200 response is
appended to <out_dir>/log.jsonl. Failed requests are repeated, never skipped.
"""
import http.client
import json
import os
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
MAX_ATTEMPTS = 60


class Client:
    def __init__(self, log_path):
        self.token = None
        self.log_path = log_path
        self.requests = 0

    def log(self, **event):
        event["t"] = time.time()
        with open(self.log_path, "a") as f:
            f.write(json.dumps(event) + "\n")

    def _raw(self, method, path, auth):
        self.requests += 1
        req = urllib.request.Request(BASE + path, method=method)
        if auth:
            req.add_header("Authorization", f"Bearer {self.token}")
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()
        except (urllib.error.URLError, http.client.HTTPException, OSError) as e:
            return None, {}, repr(e).encode()

    @staticmethod
    def _retry_after(headers, body):
        for k, v in headers.items():
            if k.lower() == "retry-after":
                try:
                    return float(v)
                except ValueError:
                    pass
        try:
            return float(json.loads(body)["retry_after"])
        except Exception:
            return 1.0

    def refresh_token(self):
        for attempt in range(1, MAX_ATTEMPTS + 1):
            status, headers, body = self._raw("POST", "/token", auth=False)
            if status == 200:
                try:
                    self.token = json.loads(body)["token"]
                    self.log(kind="token", path="/token", status=200, token=self.token)
                    return
                except Exception:
                    self.log(kind="bad_body", path="/token", status=200, body=body[:300].decode("utf-8", "replace"))
                    time.sleep(1)
                    continue
            self.log(kind="error", path="/token", status=status, body=body[:300].decode("utf-8", "replace"))
            time.sleep(self._retry_after(headers, body) if status == 429 else min(2 ** attempt * 0.25, 5))
        raise RuntimeError("could not obtain token")

    def get(self, path, validate, allow_404=False):
        """GET an authenticated path, repeating until a response passes validate()."""
        not_found = 0
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if self.token is None:
                self.refresh_token()
            status, headers, body = self._raw("GET", path, auth=True)
            text = body[:300].decode("utf-8", "replace")
            if status == 200:
                try:
                    data = json.loads(body)
                except ValueError:
                    self.log(kind="bad_json", path=path, status=200, body=text)
                    time.sleep(0.5)
                    continue
                problem = validate(data)
                if problem is None:
                    return data
                self.log(kind="invalid", path=path, status=200, problem=problem, body=text)
                time.sleep(0.5)
                continue
            self.log(kind="error", path=path, status=status, body=text,
                     retry_after=headers.get("Retry-After"))
            if status == 401:
                self.token = None
            elif status == 429:
                time.sleep(self._retry_after(headers, body) + 0.05)
            elif status == 404 and allow_404:
                not_found += 1
                if not_found >= 5:  # confirmed, not a transient miss
                    return None
                time.sleep(1)
            else:
                time.sleep(min(2 ** attempt * 0.25, 5))
        raise RuntimeError(f"giving up on {path} after {MAX_ATTEMPTS} attempts")


ORDER_KEYS = {"id", "customer_id", "status", "placed_at", "amount_cents"}


def page_validator(n):
    def validate(d):
        if not isinstance(d, dict):
            return "not an object"
        missing = {"page", "total_pages", "items", "next"} - d.keys()
        if missing:
            return f"missing keys {sorted(missing)}"
        if d["page"] != n:
            return f"page field {d['page']!r} != requested {n}"
        if not isinstance(d["items"], list):
            return "items not a list"
        for o in d["items"]:
            if not isinstance(o, dict) or not ORDER_KEYS <= o.keys():
                return f"malformed item {o!r}"[:200]
        return None
    return validate


def customer_validator(cid):
    def validate(d):
        if not isinstance(d, dict):
            return "not an object"
        missing = {"id", "region", "discount_pct"} - d.keys()
        if missing:
            return f"missing keys {sorted(missing)}"
        if d["id"] != cid:
            return f"id {d['id']!r} != requested {cid!r}"
        return None
    return validate


def fetch_pages(client, out_dir):
    os.makedirs(os.path.join(out_dir, "pages"), exist_ok=True)
    path, n, visited = "/orders?page=1", 1, []
    while path is not None:
        data = client.get(path, page_validator(n))
        with open(os.path.join(out_dir, "pages", f"page_{n:03d}.json"), "w") as f:
            json.dump(data, f)
        visited.append((n, path, data["total_pages"], len(data["items"]), data["next"]))
        print(f"page {n}/{data['total_pages']}: {len(data['items'])} items, next={data['next']}", flush=True)
        path = data["next"]
        if path is not None:
            expected = f"/orders?page={n + 1}"
            if path != expected:
                client.log(kind="note", path=path, problem=f"next link differs from {expected}")
            n += 1
    with open(os.path.join(out_dir, "visited.json"), "w") as f:
        json.dump(visited, f)


def fetch_customers(client, pages_dirs, cust_dir):
    os.makedirs(cust_dir, exist_ok=True)
    ids = set()
    for pages_dir in pages_dirs:
        for name in sorted(os.listdir(pages_dir)):
            with open(os.path.join(pages_dir, name)) as f:
                ids.update(o["customer_id"] for o in json.load(f)["items"])
    print(f"{len(ids)} distinct customer ids", flush=True)
    for cid in sorted(ids, key=str):
        target = os.path.join(cust_dir, f"{cid}.json")
        if os.path.exists(target):  # cached from an earlier run
            continue
        data = client.get(f"/customers/{urllib.request.quote(str(cid), safe='')}",
                          customer_validator(cid), allow_404=True)
        with open(target, "w") as f:
            json.dump({"requested_id": cid, "found": data is not None, "record": data}, f)


def main():
    out_dir = sys.argv[1]
    os.makedirs(out_dir, exist_ok=True)
    client = Client(os.path.join(out_dir, "log.jsonl"))
    if "--customers" in sys.argv:
        pages_dirs = [os.path.join(out_dir, d, "pages") for d in sorted(os.listdir(out_dir))
                      if os.path.isdir(os.path.join(out_dir, d, "pages"))]
        fetch_customers(client, pages_dirs, os.path.join(out_dir, "customers"))
    else:
        fetch_pages(client, out_dir)
    print(f"done, {client.requests} HTTP requests", flush=True)


if __name__ == "__main__":
    main()

