#!/usr/bin/env python3
"""Compute the spring-quarter shipped-order totals from the saved API data.

Usage: compute.py <pages_dir> <customers_dir> <out_json>
"""
import json
import os
import sys
from datetime import datetime, timezone

START = datetime(2025, 3, 1, tzinfo=timezone.utc)  # inclusive
END = datetime(2025, 6, 1, tzinfo=timezone.utc)    # exclusive: all of 31 May UTC is in range
REGIONS = ("north", "south", "east", "west")


def load_listings(pages_dir):
    listings = []
    for name in sorted(os.listdir(pages_dir)):
        with open(os.path.join(pages_dir, name)) as f:
            listings.extend(json.load(f)["items"])
    return listings


def load_customers(customers_dir):
    customers = {}
    for name in os.listdir(customers_dir):
        with open(os.path.join(customers_dir, name)) as f:
            entry = json.load(f)
        customers[entry["requested_id"]] = entry["record"] if entry["found"] else None
    return customers


def to_utc(ts):
    dt = datetime.fromisoformat(ts)
    if dt.tzinfo is None:
        raise ValueError(f"timestamp without offset: {ts!r}")
    return dt.astimezone(timezone.utc)


def discounted_cents(amount_cents, discount_pct):
    """amount * (100 - pct) / 100, rounded half up to a whole cent, in integers."""
    if amount_cents < 0 or not 0 <= discount_pct <= 100:
        raise ValueError(f"unexpected amount/discount {amount_cents}/{discount_pct}")
    return (amount_cents * (100 - discount_pct) + 50) // 100


def main():
    pages_dir, customers_dir, out_path = sys.argv[1:4]
    listings = load_listings(pages_dir)
    customers = load_customers(customers_dir)

    orders, duplicates_skipped = {}, 0
    for o in listings:
        if o["id"] in orders:
            duplicates_skipped += 1
            continue
        orders[o["id"]] = o

    by_region = dict.fromkeys(REGIONS, 0)
    order_count = 0
    for o in orders.values():
        if o["status"] != "shipped":
            continue
        if not START <= to_utc(o["placed_at"]) < END:
            continue
        customer = customers[o["customer_id"]]
        if customer is None:
            raise LookupError(f"{o['id']}: unknown customer {o['customer_id']}")
        by_region[customer["region"]] += discounted_cents(o["amount_cents"], customer["discount_pct"])
        order_count += 1

    result = {
        "total_cents": sum(by_region.values()),
        "order_count": order_count,
        "duplicates_skipped": duplicates_skipped,
        "by_region": by_region,
    }
    with open(out_path, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

